import { code } from '../../code.ts';
import { displayName, header, iosClass, pascal, registerFunction } from '../names.ts';
import type { Plugin } from '../values.ts';

// The path of the file in plugins/ios.
export const path = ({ id }: Plugin) => `${id}/src/${pascal(id)}.mm`;

export default ({ id }: Plugin) => {
  const className = iosClass(id);
  const product = pascal(id);
  return code`
// clang-format off
// Generated by plugins/tools/generate.ts from plugins/plugins/${id}/plugin.json; do not edit.
#import <${product}/${product}.h>

#include "${header(id)}"

NSErrorDomain const ${className}ErrorDomain = @"org.maplibre.plugins.${id}";

@implementation ${className}

+ (BOOL)registerPluginWithError:(NSError **)error {
    char message[512] = {};
    const mln_plugin_status status = ${registerFunction(id)}(&mln_plugin_register_v1, message, sizeof(message));
    if (status == MLN_PLUGIN_STATUS_OK || status == MLN_PLUGIN_STATUS_ALREADY_REGISTERED) {
        return YES;
    }
    if (error) {
        NSString *description = message[0] ? [NSString stringWithUTF8String:message]
                                            : @"MapLibre rejected the ${displayName(id)} plugin";
        *error = [NSError errorWithDomain:${className}ErrorDomain
                                     code:status
                                 userInfo:@{NSLocalizedDescriptionKey: description ?: @""}];
    }
    return NO;
}

@end
`;
};
